    name: { de: "Kathedrale des Heiligen Jakob", hu: "Szent Jakab-székesegyház", ro: "Catedrala Sfântul Iacob", en: "St. James Cathedral"},
    image: "/poi-images/croatia-sibenik-cathedral-history-v2.webp",
